using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// The Metadata of a Behavior: its Variable and Signal definitions, and the behavior-wide default values
/// assigned in the Inspector. Generated by the editor for every <see cref="SchematicBehavior"/> type, and used as
/// a lookup when creating a <see cref="BehaviorRuntime"/>.<br/>
/// Per-object default overrides live on the <see cref="SchematicObject"/>'s <see cref="BehaviorAttachment"/>, so they
/// follow the prefab through duplication, prefab variants and scene instances.
/// </summary>
public class BehaviorMetadata : ScriptableObjectWithID<BehaviorMetadata>
{
    private static Dictionary<Type, BehaviorMetadata> _byType;

    /// <summary>
    /// Gets the Behavior Metadata for the given Behavior Type, or null if none has been generated.
    /// </summary>
    public static BehaviorMetadata Get(Type behaviorType)
    {
        if (behaviorType == null)
            return null;

        if (_byType == null || !_byType.TryGetValue(behaviorType, out var metadata) || metadata == null)
        {
            _byType = new Dictionary<Type, BehaviorMetadata>();
            foreach (var loaded in Resources.LoadAll<BehaviorMetadata>(""))
            {
                var type = loaded.BehaviorType.Type;
                if (type != null)
                    _byType[type] = loaded;
            }
            _byType.TryGetValue(behaviorType, out metadata);
        }

        return metadata;
    }

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    private static void ResetStatics() => _byType = null;

    [HideInInspector]
    public SerializableType BehaviorType;

    /// <summary>
    /// The Variables declared by the Behavior, in declaration order.
    /// </summary>
    public List<VariableDefinition> Variables = new();

    /// <summary>
    /// The Signals declared by the Behavior.
    /// </summary>
    public List<SignalDefinition> Signals = new();

    public SignalDefinition FindSignal(string name)
    {
        foreach (var signal in Signals)
            if (signal.Name == name)
                return signal;
        return null;
    }

    public VariableDefinition FindVariable(string name)
    {
        foreach (var variable in Variables)
            if (variable.Name == name)
                return variable;
        return null;
    }
}

[Serializable]
public class VariableDefinition
{
    public string Name;
    public SerializableType Type;

    /// <summary>
    /// Mirrors the default in code unless <see cref="OverrideDefault"/> is set, in which case it replaces it for every instance.
    /// </summary>
    public SchematicValue Default = new();
    public bool OverrideDefault;
}

public enum SignalDirection
{
    Unspecified,
    Input,
    Output,
}

[Serializable]
public class SignalDefinition
{
    public string Name;
    public SignalDirection Direction;
    public List<SignalParameterDefinition> Parameters = new();

    /// <summary>
    /// The Signal asset (stored inside the Metadata asset) that the Behavior sends and listens on. Drag it into a
    /// Schematic Graph to send or receive this Signal there.
    /// </summary>
    public SignalData Asset;
}

[Serializable]
public class SignalParameterDefinition
{
    public string Name;
    public SerializableType Type;
}
